import java.util.*;
import java.util.stream.Collectors;

public class CollectorPitfallDemo {
    record User(String id, String role) {}

    public static void main(String[] args) {
        List<User> users = List.of(
            new User("admin_1", "ADMIN"),
            new User("admin_2", "ADMIN"),
            new User("user_1", "GUEST")
        );

        // PITFALL: This will throw IllegalStateException due to duplicate "ADMIN" keys!
        // Map<String, String> badMap = users.stream()
        //     .collect(Collectors.toMap(User::role, User::id));

        // PRODUCTION-SAFE: Provide a merge function (e.g., keep existing or pick latest)
        Map<String, String> safeMap = users.stream()
            .collect(Collectors.toMap(
                User::role,
                User::id,
                (existingId, newId) -> existingId // Collision resolution strategy
            ));

        System.out.println(safeMap);
    }
}
